export const OFFLINE_ORGANIZATION_ID = 'org_offline';
export const isOfflineOrganizationId = (organizationId: string) => organizationId === OFFLINE_ORGANIZATION_ID;
export const buildOfflineOrganization = (): Organization => ({
  id: OFFLINE_ORGANIZATION_ID,
  name: 'Offline workspace',
  picture: null,
  owner_first_name: null,
  owner_last_name: null,
  owner_email: null,
  total_members: 1,
  total_invites: 0,
  total_admins: 1,
  is_owner: true,
  can_leave: false,
});

export const SCRATCHPAD_ORGANIZATION_ID = 'org_scratchpad';

export const getInitialEntry = async () => {
  if (OFFLINE_BUILD) {
    return getInitialRouteForOrganization({ organizationId: OFFLINE_ORGANIZATION_ID, navigateToWorkspace: true });
  }

const createProjectImpl = async (organizationId: string, newProjectData: CreateProjectData) => {
  if (OFFLINE_BUILD) {
    invariant(organizationId === OFFLINE_ORGANIZATION_ID, 'Select the offline organization to create a project');
    invariant(newProjectData.storageType === 'local', 'Only local storage is available in this offline build');
    invariant(typeof newProjectData.name === 'string' && newProjectData.name.trim().length > 0, 'Project name is required');
    const project = await services.project.create({ name: newProjectData.name, parentId: organizationId });
    return project._id;
  }

